	@Test
	void twoSnapshotPassesPublishMappedLeafAndProjectedDistinctEvidence(@TempDir Path directory) throws Exception {
		SyntheticSnapshot snapshot = correlatedSnapshot();
		Class<?> configType = Class.forName(
				"org.eclipse.rdf4j.sail.lmdb.frontier.FrontierStatisticsBuildConfig");
		Object config = configType
				.getMethod("testing", long.class, int.class, int.class, int.class, long.class)
				.invoke(null, 32L * 1024L * 1024L, 64, 32, 256, 2L * 1024L * 1024L);
		FrontierStatisticsHeapGovernor governor = new FrontierStatisticsHeapGovernor(
				64L * 1024L * 1024L, 8L * 1024L * 1024L, 16L * 1024L * 1024L, 8L * 1024L * 1024L);
		Class<?> builderType = Class.forName(
				"org.eclipse.rdf4j.sail.lmdb.frontier.FrontierStatisticsBuilder");
		Method build = builderType.getMethod("build", Path.class, long.class, long.class,
				FrontierSnapshotSource.class, FrontierStatisticsHeapGovernor.class, configType);

		FrontierStatisticsManifest manifest = (FrontierStatisticsManifest) build.invoke(
				null, directory, 1L, -1L, snapshot, governor, config);

		assertEquals(4, snapshot.scanCalls,
				"two passes over explicit and inferred planes must be the only snapshot scans");
		assertEquals(2L * snapshot.totalRows(), snapshot.visitedRows,
				"every statement must be visited exactly twice");
		assertTrue(manifest.shards()
				.stream()
				.filter(shard -> shard.tier() == FrontierStatisticsTier.EXACT_AND_LINEAR
						|| shard.tier() == FrontierStatisticsTier.LEAF_WITNESSES)
				.allMatch(FrontierStatisticsShardDescriptor::mandatory));
		assertTrue(manifest.shards()
				.stream()
				.filter(shard -> shard.kind() == FrontierStatisticsShardKind.CENTER_SAMPLES)
				.noneMatch(FrontierStatisticsShardDescriptor::mandatory),
				"optional center refinements must not determine generation readiness");
		assertTrue(manifest.shards()
				.stream()
				.anyMatch(shard -> shard.kind() == FrontierStatisticsShardKind.OMNI_CELL_DIRECTORY));
		assertTrue(manifest.shards()
				.stream()
				.anyMatch(shard -> shard.kind() == FrontierStatisticsShardKind.OMNI_POSTINGS));
		assertTrue(manifest.shards()
				.stream()
				.anyMatch(shard -> shard.kind() == FrontierStatisticsShardKind.PROJECTED_DISTINCT));

		try (LmdbStatisticsService service = LmdbStatisticsService.open(
				directory, governor, 32L * 1024L * 1024L, 60_000L)) {
			service.publish(manifest);
			Class<?> probeType = Class.forName(
					"org.eclipse.rdf4j.sail.lmdb.frontier.FrontierLeafProbe");
			Constructor<?> probeConstructor = probeType.getConstructor(
					int.class, int.class, long.class, long.class, long.class, long.class);
			Object predicateSeven = probeConstructor.newInstance(1, 2, 0L, 7L, 0L, 0L);
			Object estimate = LmdbStatisticsService.class
					.getMethod("estimateLeaf", long.class, probeType)
					.invoke(service, snapshot.snapshotEpoch(), predicateSeven);
			Class<?> estimateType = estimate.getClass();
			double point = (double) estimateType.getMethod("pointRows").invoke(estimate);
			double lower = (double) estimateType.getMethod("lowerRows").invoke(estimate);
			double upper = (double) estimateType.getMethod("upperRows").invoke(estimate);
			assertTrue(lower <= 6_000.0 && 6_000.0 <= upper);
			assertTrue(point >= 3_000.0 && point <= 12_000.0,
					"leaf q-error must be at most two on the correlated qualification fixture");

			double distinct = (double) LmdbStatisticsService.class
					.getMethod("estimateProjectedDistinct", long.class, probeType, int.class)
					.invoke(service, snapshot.snapshotEpoch(), predicateSeven, 0);
			assertTrue(distinct >= 50.0 && distinct <= 200.0,
					"projected subject distinct q-error must be at most two");
		}
	}

	@Test
	void heavyProjectedDistinctIsPersistedAsQueryReadyPlaneUnionScalars(@TempDir Path directory) throws Exception {
		SyntheticSnapshot snapshot = new SyntheticSnapshot(81L, List.of(
				new long[] { 1L, 7L, 10L, 0L },
				new long[] { 2L, 7L, 20L, 0L },
				new long[] { 2L, 7L, 21L, 101L }),
				List.of(
						new long[] { 2L, 7L, 30L, 0L },
						new long[] { 3L, 7L, 40L, 101L }));
		FrontierStatisticsBuildConfig config = FrontierStatisticsBuildConfig.testing(
				32L * 1024L * 1024L, 64, 32, 256, 2L * 1024L * 1024L);
		FrontierStatisticsHeapGovernor governor = new FrontierStatisticsHeapGovernor(
				64L * 1024L * 1024L, 8L * 1024L * 1024L, 16L * 1024L * 1024L, 8L * 1024L * 1024L);

		FrontierStatisticsManifest manifest = FrontierStatisticsBuilder.build(
				directory, 1L, -1L, snapshot, governor, config);
		FrontierStatisticsShardDescriptor descriptor = manifest.shards()
				.stream()
				.filter(shard -> shard.kind().name().equals("HEAVY_PROJECTED_DISTINCT"))
				.findFirst()
				.orElseThrow();

		try (FrontierStatisticsShard shard = FrontierStatisticsShard.open(directory.resolve(descriptor.fileName()))) {
			assertEquals(13, shard.columnCount(),
					"one predicate key plus four components by three statement-plane masks must be query-ready");
			assertEquals(7L, shard.column(0).value(0L));
			assertEquals(2L, shard.column(1).value(0L), "explicit distinct subjects");
			assertEquals(2L, shard.column(2).value(0L), "inferred distinct subjects");
			assertEquals(3L, shard.column(3).value(0L), "union distinct subjects must deduplicate overlap");
			assertEquals(1L, shard.column(4).value(0L), "a predicate-specific projection is deterministic");
			assertEquals(1L, shard.column(5).value(0L));
			assertEquals(1L, shard.column(6).value(0L));
			assertEquals(3L, shard.column(7).value(0L), "explicit distinct objects");
			assertEquals(2L, shard.column(8).value(0L), "inferred distinct objects");
			assertEquals(5L, shard.column(9).value(0L), "union distinct objects");
		}

		FrontierStatisticsShardDescriptor defaultContextDescriptor = manifest.shards()
				.stream()
				.filter(shard -> shard.kind().name().equals("HEAVY_DEFAULT_PROJECTED_DISTINCT"))
				.findFirst()
				.orElseThrow();
		try (FrontierStatisticsShard shard = FrontierStatisticsShard.open(
				directory.resolve(defaultContextDescriptor.fileName()))) {
			assertEquals(13, shard.columnCount());
			assertEquals(7L, shard.column(0).value(0L));
			assertEquals(2L, shard.column(1).value(0L), "default explicit distinct subjects");
			assertEquals(1L, shard.column(2).value(0L), "default inferred distinct subjects");
			assertEquals(2L, shard.column(3).value(0L), "default union distinct subjects");
			assertEquals(2L, shard.column(7).value(0L), "default explicit distinct objects");
			assertEquals(1L, shard.column(8).value(0L), "default inferred distinct objects");
			assertEquals(3L, shard.column(9).value(0L), "default union distinct objects");
			assertEquals(1L, shard.column(10).value(0L), "the default-context projection is deterministic");
			assertEquals(1L, shard.column(11).value(0L));
			assertEquals(1L, shard.column(12).value(0L));
		}
		assertTrue(manifest.shards()
				.stream()
				.noneMatch(shard -> shard.kind() == FrontierStatisticsShardKind.DISTINCT_HLL),
				"query-ready heavy scalars must replace duplicate per-plane HLL shards");
		assertTrue(manifest.shards()
				.stream()
				.noneMatch(shard -> shard.kind() == FrontierStatisticsShardKind.FAST_AGMS
						&& (int) shard.logicalKey() == 1),
				"predicate-specific Fast-AGMS projections are deterministic and must not consume builder memory");

		try (LmdbStatisticsService service = LmdbStatisticsService.open(
				directory, governor, 32L * 1024L * 1024L, 60_000L)) {
			service.publish(manifest);
			FrontierLeafProbe defaultPredicate = new FrontierLeafProbe(
					FrontierLeafProbe.BOTH_PLANES,
					FrontierLeafProbe.PREDICATE | FrontierLeafProbe.CONTEXT,
					0L, 7L, 0L, 0L);
			assertEquals(2.0d,
					service.estimateProjectedDistinct(snapshot.snapshotEpoch(), defaultPredicate, 0), 0.0d,
					"a default-graph probe must read the scoped heavy-predicate scalar instead of sparse Omni cells");
			assertEquals(3.0d,
					service.estimateProjectedDistinct(snapshot.snapshotEpoch(), defaultPredicate, 2), 0.0d);
		}
	}

	@Test
	void heavyConditionalCountsPreserveDefaultAndNamedContextSemantics(@TempDir Path directory) throws Exception {
		SyntheticSnapshot snapshot = new SyntheticSnapshot(83L, List.of(
				new long[] { 1L, 7L, 10L, 0L },
				new long[] { 2L, 7L, 10L, 0L },
				new long[] { 3L, 7L, 10L, 101L },
				new long[] { 4L, 7L, 20L, 101L },
				new long[] { 5L, 8L, 10L, 0L }), List.of());
		FrontierStatisticsBuildConfig config = FrontierStatisticsBuildConfig.testing(
				32L * 1024L * 1024L, 64, 32, 256, 2L * 1024L * 1024L);
		FrontierStatisticsHeapGovernor governor = new FrontierStatisticsHeapGovernor(
				64L * 1024L * 1024L, 8L * 1024L * 1024L, 16L * 1024L * 1024L, 8L * 1024L * 1024L);
		FrontierStatisticsManifest manifest = FrontierStatisticsBuilder.build(
				directory, 1L, -1L, snapshot, governor, config);

		try (LmdbStatisticsService service = LmdbStatisticsService.open(
				directory, governor, 32L * 1024L * 1024L, 60_000L)) {
			service.publish(manifest);
			assertExactRows(service, snapshot.snapshotEpoch(), new FrontierLeafProbe(
					FrontierLeafProbe.EXPLICIT,
					FrontierLeafProbe.PREDICATE | FrontierLeafProbe.CONTEXT,
					0L, 7L, 0L, 0L), 2.0d);
			assertExactRows(service, snapshot.snapshotEpoch(), new FrontierLeafProbe(
					FrontierLeafProbe.EXPLICIT,
					FrontierLeafProbe.PREDICATE | FrontierLeafProbe.OBJECT | FrontierLeafProbe.CONTEXT,
					0L, 7L, 10L, 0L), 2.0d);
			assertExactRows(service, snapshot.snapshotEpoch(), new FrontierLeafProbe(
					FrontierLeafProbe.EXPLICIT,
					FrontierLeafProbe.PREDICATE | FrontierLeafProbe.OBJECT | FrontierLeafProbe.CONTEXT,
					0L, 7L, 20L, 0L), 0.0d);
			assertExactRows(service, snapshot.snapshotEpoch(), new FrontierLeafProbe(
					FrontierLeafProbe.EXPLICIT, FrontierLeafProbe.PREDICATE,
					0L, 7L, 0L, 0L, 0, true), 2.0d);
			assertExactRows(service, snapshot.snapshotEpoch(), new FrontierLeafProbe(
					FrontierLeafProbe.EXPLICIT,
					FrontierLeafProbe.PREDICATE | FrontierLeafProbe.OBJECT,
					0L, 7L, 10L, 0L, 0, true), 1.0d);
		}
	}

	private static void assertExactRows(LmdbStatisticsService service, long epoch, FrontierLeafProbe probe,
			double expected) {
		FrontierLeafEstimate estimate = service.estimateLeaf(epoch, probe);
		assertEquals(expected, estimate.pointRows(), 0.0d, estimate.toString());
		assertEquals(expected, estimate.lowerRows(), 0.0d, estimate.toString());
		assertEquals(expected, estimate.upperRows(), 0.0d, estimate.toString());
		if (!probe.namedContextsOnly()) {
			assertEquals("frontier-v2-exact", estimate.source(),
					"the conditional scalar shard, rather than incidental complete Omni cells, must prove the result");
		}
	}

	@Test
	void namedContextProjectedDistinctIsQueryReadyAcrossStatementPlanes(@TempDir Path directory) throws Exception {
		SyntheticSnapshot snapshot = new SyntheticSnapshot(82L, List.of(
				new long[] { 1L, 5L, 10L, 0L },
				new long[] { 2L, 7L, 20L, 101L },
				new long[] { 3L, 8L, 30L, 102L }),
				List.of(
						new long[] { 4L, 8L, 40L, 103L },
						new long[] { 5L, 9L, 50L, 104L }));
		FrontierStatisticsBuildConfig config = FrontierStatisticsBuildConfig.testing(
				32L * 1024L * 1024L, 64, 32, 256, 2L * 1024L * 1024L);
		FrontierStatisticsHeapGovernor governor = new FrontierStatisticsHeapGovernor(
				64L * 1024L * 1024L, 8L * 1024L * 1024L, 16L * 1024L * 1024L, 8L * 1024L * 1024L);
		FrontierStatisticsManifest manifest = FrontierStatisticsBuilder.build(
				directory, 1L, -1L, snapshot, governor, config);

		assertTrue(manifest.shards()
				.stream()
				.anyMatch(shard -> shard.kind().name().equals("NAMED_PROJECTED_DISTINCT")));
		try (LmdbStatisticsService service = LmdbStatisticsService.open(
				directory, governor, 32L * 1024L * 1024L, 60_000L)) {
			service.publish(manifest);
			assertProjectedDistinctNear(service, snapshot.snapshotEpoch(), FrontierLeafProbe.EXPLICIT, 2.0d);
			assertProjectedDistinctNear(service, snapshot.snapshotEpoch(), FrontierLeafProbe.INFERRED, 2.0d);
			assertProjectedDistinctNear(service, snapshot.snapshotEpoch(), FrontierLeafProbe.BOTH_PLANES, 3.0d);
		}
	}

	private static void assertProjectedDistinctNear(LmdbStatisticsService service, long epoch, int planeMask,
			double expected) {
		FrontierLeafProbe namedContexts = new FrontierLeafProbe(planeMask, 0, 0L, 0L, 0L, 0L, 0, true);
		double actual = service.estimateProjectedDistinct(epoch, namedContexts, 1);
		assertTrue(actual >= expected * 0.9d && actual <= expected * 1.1d,
				() -> "named-context projected distinct should remain within ten percent: " + actual
						+ ", leaf=" + service.estimateLeaf(epoch, namedContexts) + ", status=" + service.status());
	}

