	@Test
	void highDegreeCenterUsesBoundedSecondStageNeighborSamples(@TempDir Path directory) throws Exception {
		int rows = 60_000;
		FrontierStatisticsBuildConfig config = FrontierStatisticsBuildConfig.testing(
				32L * 1024L * 1024L, 64, 1, 256, 2L * 1024L * 1024L);
		FrontierStatisticsHeapGovernor governor = new FrontierStatisticsHeapGovernor(
				64L * 1024L * 1024L, 8L * 1024L * 1024L, 16L * 1024L * 1024L,
				8L * 1024L * 1024L);

		FrontierStatisticsManifest manifest = FrontierStatisticsBuilder.build(
				directory, 1L, -1L, new HighDegreeCenterSnapshot(rows), governor, config);
		List<FrontierStatisticsShardDescriptor> subjectDomains = manifest.shards()
				.stream()
				.filter(shard -> shard.kind() == FrontierStatisticsShardKind.CENTER_SAMPLES)
				.filter(shard -> (int) (shard.logicalKey() >>> 32) == 0)
				.filter(shard -> (int) shard.logicalKey() == 0)
				.toList();

		assertEquals(config.designLaneCount(), subjectDomains.size(), subjectDomains::toString);
		assertTrue(subjectDomains.stream().allMatch(shard -> shard.rowCount() > 0L), subjectDomains::toString);
		assertTrue(subjectDomains.stream().allMatch(shard -> shard.rowCount() < rows),
				"a selected high-degree center must use a bounded neighbor sample, not retain its complete adjacency");
		assertTrue(subjectDomains.stream().allMatch(shard -> shard.minimumKey() == Long.MAX_VALUE),
				"the lone subject center must be included in every design lane");
		assertTrue(subjectDomains.stream().allMatch(shard -> shard.maximumKey() < Long.MAX_VALUE),
				"the descriptor must persist an independent second-stage row threshold");

		double exact = (double) (rows / 2) * (rows / 2);
		FrontierLeafProbe predicateSeven = new FrontierLeafProbe(
				FrontierLeafProbe.EXPLICIT, FrontierLeafProbe.PREDICATE, 0L, 7L, 0L, 0L);
		FrontierLeafProbe predicateEight = new FrontierLeafProbe(
				FrontierLeafProbe.EXPLICIT, FrontierLeafProbe.PREDICATE, 0L, 8L, 0L, 0L);
		try (LmdbStatisticsService service = LmdbStatisticsService.open(
				directory, governor, 32L * 1024L * 1024L, 60_000L)) {
			service.publish(manifest);
			FrontierJoinEstimate estimate = service.estimateJoin(
					1L, new FrontierJoinProbe(predicateSeven, 0, predicateEight, 0));

			assertEquals("frontier-v2-omni-center", estimate.source());
			assertTrue(estimate.pointRows() >= exact * 0.75d && estimate.pointRows() <= exact * 1.25d,
					estimate::toString);
			assertTrue(estimate.lowerRows() <= exact && exact <= estimate.upperRows(), estimate::toString);
			assertTrue(estimate.lowerRows() < estimate.pointRows() || estimate.pointRows() < estimate.upperRows(),
					"second-stage sampling must never be reported as exact");
		}
	}

