	@Test
	void mappedOmniStopsAtTheFirstStrongPriorityTier(@TempDir Path directory) throws Exception {
		SyntheticSnapshot snapshot = correlatedSnapshot();
		FrontierStatisticsBuildConfig config = FrontierStatisticsBuildConfig.testing(
				32L * 1024L * 1024L, 64, 256, 256, 2L * 1024L * 1024L);
		FrontierStatisticsHeapGovernor governor = new FrontierStatisticsHeapGovernor(
				64L * 1024L * 1024L, 8L * 1024L * 1024L, 16L * 1024L * 1024L, 8L * 1024L * 1024L);
		FrontierStatisticsManifest manifest = FrontierStatisticsBuilder.build(
				directory, 1L, -1L, snapshot, governor, config);
		HashMap<Integer, FrontierStatisticsShard> shards = new HashMap<>();
		try {
			for (FrontierStatisticsShardDescriptor descriptor : manifest.shards()) {
				shards.put(descriptor.shardId(),
						FrontierStatisticsShard.open(directory.resolve(descriptor.fileName())));
			}
			FrontierOmniIndex index = new FrontierOmniIndex(manifest, shards);
			FrontierOmniIndex.Scratch scratch = new FrontierOmniIndex.Scratch();
			FrontierLeafEstimate estimate = index.estimateLeaf(new FrontierLeafProbe(
					FrontierLeafProbe.EXPLICIT, FrontierLeafProbe.PREDICATE, 0L, 7L, 0L, 0L), scratch);
			Method visitedRows = FrontierOmniIndex.Scratch.class.getDeclaredMethod("candidateRowsVisited");
			visitedRows.setAccessible(true);
			long actualVisited = ((Number) visitedRows.invoke(scratch)).longValue();

			assertEquals(FrontierFallbackReason.NONE, estimate.fallbackReason(), estimate::toString);
			assertTrue(estimate.lowerRows() <= 6_000.0d && 6_000.0d <= estimate.upperRows(), estimate::toString);
			assertTrue(estimate.confidence() > 0.95d, estimate::toString);
			assertTrue(actualVisited <= 4L * 64L,
					() -> "four stable design lanes should stop after one 64-row priority tier, visited="
							+ actualVisited);

			FrontierOmniIndex.Scratch sparseScratch = new FrontierOmniIndex.Scratch();
			FrontierLeafEstimate absent = index.estimateLeaf(new FrontierLeafProbe(
					FrontierLeafProbe.EXPLICIT,
					FrontierLeafProbe.SUBJECT | FrontierLeafProbe.OBJECT,
					1L, 0L, 10_200L, 0L), sparseScratch);
			long sparseVisited = ((Number) visitedRows.invoke(sparseScratch)).longValue();
			assertEquals(0.0d, absent.pointRows(), absent::toString);
			assertEquals(0.0d, absent.upperRows(),
					"a weak first tier must enrich until the complete candidate cell proves absence");
			assertTrue(sparseVisited > 64L,
					() -> "zero initial witnesses must request a larger persisted tier, visited=" + sparseVisited);
		} finally {
			for (FrontierStatisticsShard shard : shards.values()) {
				shard.close();
			}
		}
	}

	@Test
	void mappedOmniIntervalsCoverEveryBoundMaskAndStatementPlane(@TempDir Path directory) throws Exception {
		SyntheticSnapshot snapshot = correlatedSnapshot();
		FrontierStatisticsBuildConfig config = FrontierStatisticsBuildConfig.testing(
				32L * 1024L * 1024L, 64, 32, 256, 2L * 1024L * 1024L);
		FrontierStatisticsHeapGovernor governor = new FrontierStatisticsHeapGovernor(
				64L * 1024L * 1024L, 8L * 1024L * 1024L, 16L * 1024L * 1024L, 8L * 1024L * 1024L);
		FrontierStatisticsManifest manifest = FrontierStatisticsBuilder.build(
				directory, 1L, -1L, snapshot, governor, config);

		try (LmdbStatisticsService service = LmdbStatisticsService.open(
				directory, governor, 32L * 1024L * 1024L, 60_000L)) {
			service.publish(manifest);
			for (int planeMask : new int[] {
					FrontierLeafProbe.EXPLICIT, FrontierLeafProbe.INFERRED, FrontierLeafProbe.BOTH_PLANES }) {
				long[] tuple = planeMask == FrontierLeafProbe.INFERRED
						? snapshot.inferred.get(0)
						: snapshot.explicit.get(0);
				for (int boundMask = 1; boundMask <= FrontierLeafProbe.ALL_COMPONENTS; boundMask++) {
					FrontierLeafProbe probe = new FrontierLeafProbe(planeMask, boundMask,
							tuple[0], tuple[1], tuple[2], tuple[3]);
					long exact = snapshot.exactCount(probe);
					FrontierLeafEstimate estimate = service.estimateLeaf(snapshot.snapshotEpoch(), probe);
					assertEquals(FrontierFallbackReason.NONE, estimate.fallbackReason(),
							"plane=" + planeMask + ", mask=" + boundMask);
					assertTrue(estimate.source().startsWith("frontier-v2-"), estimate::source);
					assertTrue(estimate.lowerRows() <= exact && exact <= estimate.upperRows(),
							"plane=" + planeMask + ", mask=" + boundMask + ", exact=" + exact
									+ ", estimate=" + estimate);
				}
			}

			FrontierLeafProbe absentCorrelation = new FrontierLeafProbe(
					FrontierLeafProbe.EXPLICIT,
					FrontierLeafProbe.SUBJECT | FrontierLeafProbe.OBJECT,
					1L, 0L, 10_200L, 0L);
			FrontierLeafEstimate absent = service.estimateLeaf(snapshot.snapshotEpoch(), absentCorrelation);
			assertEquals(0.0d, absent.lowerRows());
			assertTrue(absent.upperRows() > 0.0d,
					"an absent sampled correlation must include possible zero without claiming database-proved zero");
			assertEquals(0.0d, absent.confidence(),
					"zero shared witnesses must not manufacture confidence from a synthetic pseudo-count");
		}
	}

