	@Test
	void omniDirectoryPersistsTheActualBottomKCutoffPriority(@TempDir Path directory) throws Exception {
		SyntheticSnapshot snapshot = correlatedSnapshot();
		FrontierStatisticsBuildConfig config = FrontierStatisticsBuildConfig.testing(
				32L * 1024L * 1024L, 64, 32, 256, 2L * 1024L * 1024L);
		FrontierStatisticsHeapGovernor governor = new FrontierStatisticsHeapGovernor(
				64L * 1024L * 1024L, 8L * 1024L * 1024L, 16L * 1024L * 1024L, 8L * 1024L * 1024L);
		FrontierStatisticsManifest manifest = FrontierStatisticsBuilder.build(
				directory, 1L, -1L, snapshot, governor, config);
		FrontierStatisticsShardDescriptor directoryDescriptor = manifest.shards()
				.stream()
				.filter(descriptor -> descriptor.kind() == FrontierStatisticsShardKind.OMNI_CELL_DIRECTORY)
				.findFirst()
				.orElseThrow();

		boolean checked = false;
		try (FrontierStatisticsShard cells = FrontierStatisticsShard.open(
				directory.resolve(directoryDescriptor.fileName()))) {
			assertEquals(7, cells.columnCount());
			for (long cell = 0L; cell < cells.rowCount(); cell++) {
				int flags = Math.toIntExact(cells.column(4).value(cell));
				if ((flags & FrontierOmniCellFlags.BOTTOM_K) == 0) {
					continue;
				}
				int domainId = Math.toIntExact(cells.column(1).value(cell));
				long start = cells.column(2).value(cell);
				long count = cells.column(3).value(cell);
				FrontierStatisticsShardDescriptor tuplesDescriptor = manifest.shards()
						.stream()
						.filter(descriptor -> descriptor.kind() == FrontierStatisticsShardKind.OMNI_TUPLES
								&& descriptor.logicalKey() == domainId)
						.findFirst()
						.orElseThrow();
				FrontierStatisticsShardDescriptor postingsDescriptor = manifest.shards()
						.stream()
						.filter(descriptor -> descriptor.kind() == FrontierStatisticsShardKind.OMNI_POSTINGS
								&& descriptor.logicalKey() == domainId)
						.findFirst()
						.orElseThrow();
				try (FrontierStatisticsShard tuples = FrontierStatisticsShard.open(
						directory.resolve(tuplesDescriptor.fileName()));
						FrontierStatisticsShard postings = FrontierStatisticsShard.open(
								directory.resolve(postingsDescriptor.fileName()))) {
					long ordinal = postings.column(0).value(start + count - 1L);
					assertEquals(tuples.column(0).value(ordinal), cells.column(6).value(cell));
				}
				checked = true;
				break;
			}
		}
		assertTrue(checked, "the skewed fixture must create at least one bottom-K cell");
	}

