	@Test
	void publishedMutationLayerKeepsOmniEvidenceQueryableAcrossRestart(@TempDir Path directory) throws Exception {
		SyntheticSnapshot snapshot = new SyntheticSnapshot(10L, List.of(
				new long[] { 1L, 7L, 10L, 0L },
				new long[] { 2L, 7L, 20L, 0L },
				new long[] { 10L, 8L, 100L, 0L },
				new long[] { 20L, 8L, 200L, 0L },
				new long[] { 100L, 9L, 1_000L, 0L },
				new long[] { 200L, 9L, 2_000L, 0L }), List.of());
		FrontierStatisticsBuildConfig config = FrontierStatisticsBuildConfig.testing(
				32L * 1024L * 1024L, 64, 32, 256, 2L * 1024L * 1024L);
		FrontierStatisticsHeapGovernor governor = new FrontierStatisticsHeapGovernor(
				64L * 1024L * 1024L, 8L * 1024L * 1024L, 16L * 1024L * 1024L, 8L * 1024L * 1024L);
		FrontierStatisticsManifest base = FrontierStatisticsBuilder.build(
				directory, 1L, -1L, snapshot, governor, config);
		FrontierStatisticsManifest delta = FrontierStatisticsDeltaBuilder.build(directory, base, List.of(
				new FrontierMutation(11L, 11L, false, true, 2L, 7L, 20L, 0L),
				new FrontierMutation(12L, 11L, true, true, 3L, 7L, 30L, 0L),
				new FrontierMutation(13L, 11L, true, true, 30L, 8L, 300L, 0L),
				new FrontierMutation(14L, 11L, true, true, 300L, 9L, 3_000L, 0L)), governor, config);

		List<String> deltaKinds = delta.shards()
				.stream()
				.map(FrontierStatisticsShardDescriptor::kind)
				.map(Enum::name)
				.toList();
		assertTrue(deltaKinds.contains("OMNI_DELTA_DIRECTORY"), deltaKinds::toString);
		assertTrue(deltaKinds.contains("OMNI_DELTA_TUPLES"), deltaKinds::toString);
		assertTrue(deltaKinds.contains("OMNI_DELTA_POSTINGS"), deltaKinds::toString);

		int predicateAndDefaultGraph = FrontierLeafProbe.PREDICATE | FrontierLeafProbe.CONTEXT;
		FrontierLeafProbe predicateSeven = new FrontierLeafProbe(
				FrontierLeafProbe.EXPLICIT, predicateAndDefaultGraph, 0L, 7L, 0L, 0L);
		FrontierJoinProgram path = new FrontierJoinProgram(
				new FrontierLeafProbe[] {
						predicateSeven,
						new FrontierLeafProbe(FrontierLeafProbe.EXPLICIT, predicateAndDefaultGraph,
								0L, 8L, 0L, 0L),
						new FrontierLeafProbe(FrontierLeafProbe.EXPLICIT, predicateAndDefaultGraph,
								0L, 9L, 0L, 0L)
				},
				new int[] {
						1, 0, 2, 0,
						2, 0, 3, 0,
						3, 0, 4, 0
				});

		try (LmdbStatisticsService service = LmdbStatisticsService.open(
				directory, governor, 32L * 1024L * 1024L, 60_000L)) {
			service.publish(base);
			service.publish(delta);
		}
		try (LmdbStatisticsService reopened = LmdbStatisticsService.open(
				directory, governor, 32L * 1024L * 1024L, 60_000L)) {
			double distinctSubjects = reopened.estimateProjectedDistinct(11L, predicateSeven, 0);
			assertEquals(2.0d, distinctSubjects, 0.0d,
					"the persisted overlay must apply one deletion and one insertion to the complete base cell");

			FrontierJoinEstimate estimate = reopened.estimateSubgraph(11L, path);
			assertEquals(FrontierFallbackReason.NONE, estimate.fallbackReason(), estimate::toString);
			assertTrue(estimate.source().startsWith("frontier-v2-omni-"), estimate::toString);
			assertEquals(2.0d, estimate.pointRows(), 0.0d, estimate::toString);
			assertEquals(2.0d, estimate.lowerRows(), 0.0d, estimate::toString);
			assertEquals(2.0d, estimate.upperRows(), 0.0d, estimate::toString);
		}
	}

	@Test
	void appendHeavyMutationLayerKeepsProjectedDistinctAccurateWhenBaseCellsArePolluted(@TempDir Path directory)
			throws Exception {
		ArrayList<long[]> baseRows = new ArrayList<>();
		for (long predicate = 100L; predicate < 164L; predicate++) {
			for (long row = 0L; row < 256L; row++) {
				baseRows.add(new long[] {
						predicate * 10_000L + row, predicate, predicate * 100_000L + row, 0L
				});
			}
		}
		SyntheticSnapshot snapshot = new SyntheticSnapshot(100L, baseRows, List.of());
		FrontierStatisticsBuildConfig config = FrontierStatisticsBuildConfig.testing(
				32L * 1024L * 1024L, 2, 4, 256, 2L * 1024L * 1024L);
		FrontierStatisticsHeapGovernor governor = new FrontierStatisticsHeapGovernor(
				64L * 1024L * 1024L, 8L * 1024L * 1024L, 16L * 1024L * 1024L, 8L * 1024L * 1024L);
		FrontierStatisticsManifest base = FrontierStatisticsBuilder.build(
				directory, 1L, -1L, snapshot, governor, config);

		long deltaPredicate = 10_000L;
		int insertedSubjects = 4_096;
		ArrayList<FrontierMutation> insertions = new ArrayList<>(insertedSubjects);
		for (int row = 0; row < insertedSubjects; row++) {
			insertions.add(new FrontierMutation(101L + row, 101L, true, true,
					1_000_000L + row, deltaPredicate, 2_000_000L + row, 0L));
		}
		FrontierStatisticsManifest delta = FrontierStatisticsDeltaBuilder.build(
				directory, base, insertions, governor, config);
		FrontierLeafProbe predicate = new FrontierLeafProbe(
				FrontierLeafProbe.EXPLICIT, FrontierLeafProbe.PREDICATE | FrontierLeafProbe.CONTEXT,
				0L, deltaPredicate, 0L, 0L);

		try (LmdbStatisticsService service = LmdbStatisticsService.open(
				directory, governor, 32L * 1024L * 1024L, 60_000L)) {
			service.publish(base);
			service.publish(delta);
			double estimate = service.estimateProjectedDistinct(101L, predicate, 0);
			assertTrue(estimate >= insertedSubjects / 2.0d && estimate <= insertedSubjects * 2.0d,
					() -> "append-heavy projected distinct q-error exceeded two: " + estimate);
		}
	}

