	@Test
	void rollingCompactionKeepsLongMutationHistoryQueryableWithoutSnapshotReplay(@TempDir Path directory)
			throws Exception {
		SyntheticSnapshot snapshot = new SyntheticSnapshot(10L,
				List.of(new long[] { 1L, 7L, 10L, 0L }), List.of());
		FrontierStatisticsBuildConfig config = FrontierStatisticsBuildConfig.testing(
				64L * 1024L * 1024L, 8, 128, 64, 2L * 1024L * 1024L);
		FrontierStatisticsHeapGovernor governor = new FrontierStatisticsHeapGovernor(
				128L * 1024L * 1024L, 16L * 1024L * 1024L, 32L * 1024L * 1024L,
				16L * 1024L * 1024L);
		FrontierStatisticsManifest manifest = FrontierStatisticsBuilder.build(
				directory, 1L, -1L, snapshot, governor, config);
		int scansAfterBase = snapshot.scanCalls;

		try (LmdbStatisticsService service = LmdbStatisticsService.open(
				directory, governor, 64L * 1024L * 1024L, 60_000L)) {
			service.publish(manifest);
			for (long sequence = 11L; sequence <= 75L; sequence++) {
				try {
					manifest = service.publishDelta(List.of(new FrontierMutation(
							sequence, sequence, true, true, 100L + sequence, 7L, 1_000L + sequence, 0L)),
							config);
				} catch (IOException | RuntimeException failure) {
					throw new AssertionError("delta publication failed at sequence " + sequence, failure);
				}
				long currentLayers = manifest.shards()
						.stream()
						.filter(shard -> shard.kind() == FrontierStatisticsShardKind.SIGNED_DELTA)
						.count();
				assertTrue(currentLayers <= Long.bitCount(sequence - 10L),
						"equal-size adjacent layers must compact like a binary counter at sequence " + sequence);
			}
			long signedLayers = manifest.shards()
					.stream()
					.filter(shard -> shard.kind() == FrontierStatisticsShardKind.SIGNED_DELTA)
					.count();
			long omniLayers = manifest.shards()
					.stream()
					.filter(shard -> shard.kind() == FrontierStatisticsShardKind.OMNI_DELTA_DIRECTORY)
					.count();
			assertTrue(signedLayers <= 8L, "size-tiered compaction must keep 65 commits logarithmically bounded");
			assertEquals(signedLayers, omniLayers,
					"every compacted scalar range must retain one query-ready Omni range");
		}

		assertEquals(scansAfterBase, snapshot.scanCalls,
				"rolling compaction must consume mapped delta shards rather than replay statement storage");
		try (LmdbStatisticsService reopened = LmdbStatisticsService.open(
				directory, governor, 64L * 1024L * 1024L, 60_000L)) {
			FrontierLeafProbe predicate = new FrontierLeafProbe(
					FrontierLeafProbe.EXPLICIT, FrontierLeafProbe.PREDICATE | FrontierLeafProbe.CONTEXT,
					0L, 7L, 0L, 0L);
			FrontierLeafEstimate estimate = reopened.estimateLeaf(75L, predicate);
			assertEquals(FrontierFallbackReason.NONE, estimate.fallbackReason(), estimate::toString);
			assertEquals(66.0d, estimate.pointRows(), 0.0d, estimate::toString);
			assertEquals(66.0d, estimate.lowerRows(), 0.0d, estimate::toString);
			assertEquals(66.0d, estimate.upperRows(), 0.0d, estimate::toString);
		}
	}

